package br.com.confirmacao.scheduleblock.api;import br.com.confirmacao.audit.application.AuditService;import br.com.confirmacao.audit.domain.AuditAction;import br.com.confirmacao.scheduleblock.application.ScheduleBlockService;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import org.springframework.http.ResponseEntity;import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;import org.springframework.web.bind.annotation.*;import java.time.Instant;import java.util.*;
@RestController @RequestMapping("/api/v1/schedule-blocks")public class ScheduleBlockController{private final ScheduleBlockService service;private final AuditService audit;public ScheduleBlockController(ScheduleBlockService s,AuditService a){service=s;audit=a;}@GetMapping public List<ScheduleBlockResponse> all(JwtAuthenticationToken jwt,@RequestParam Instant start,@RequestParam Instant end){return service.find(pid(jwt),start,end).stream().map(ScheduleBlockResponse::from).toList();}@PostMapping public ScheduleBlockResponse create(JwtAuthenticationToken jwt,@Valid@RequestBody ScheduleBlockRequest request,HttpServletRequest http){var block=service.create(pid(jwt),request.startsAt(),request.endsAt(),request.reason());audit.record(AuditAction.SCHEDULE_BLOCK_CREATED,"SCHEDULE_BLOCK",block.getId(),http);return ScheduleBlockResponse.from(block);}@DeleteMapping("/{id}")public ResponseEntity<Void> delete(JwtAuthenticationToken jwt,@PathVariable UUID id,HttpServletRequest http){service.delete(pid(jwt),id);audit.record(AuditAction.SCHEDULE_BLOCK_DELETED,"SCHEDULE_BLOCK",id,http);return ResponseEntity.noContent().build();}private UUID pid(JwtAuthenticationToken j){return UUID.fromString(j.getToken().getClaimAsString("professional_id"));}}
